const gallery=document.querySelector('#gallery'), message=document.querySelector('#message');
async function request(url, options){const r=await fetch(url,options);const type=r.headers.get('content-type')||'';if(!type.includes('application/json')) throw new Error('The collection is not available right now.');const data=await r.json();if(!r.ok) throw new Error(data.error||'Request failed');return data}
function node(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
async function load(){try{const items=await request('/api/assets');gallery.replaceChildren();if(!items.length){gallery.append(node('p','No memories yet. Add your first one above.'));return}for(const item of items){const article=node('article');const media=document.createElement(item.media_type.startsWith('video/')?'video':'img');media.src='/media/'+encodeURIComponent(item.id);if(media.tagName==='VIDEO')media.controls=true;else media.alt=item.title;article.append(media);const content=node('div',null,'content');content.append(node('h3',item.title),node('p',item.description),node('small',item.uploaded_at+' UTC'));const actions=node('div',null,'actions');const edit=node('button','Edit','secondary');edit.onclick=async()=>{const title=prompt('Title',item.title);if(title===null)return;const description=prompt('Description',item.description);if(description===null)return;try{await request('/api/assets/'+item.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,description})});load()}catch(e){alert(e.message)}};const del=node('button','Delete','secondary');del.onclick=async()=>{if(!confirm('Delete this memory and its file?'))return;try{await request('/api/assets/'+item.id,{method:'DELETE'});load()}catch(e){alert(e.message)}};actions.append(edit,del);content.append(actions);article.append(content);gallery.append(article)}}catch(e){gallery.textContent=e.message}}
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,file=form.file.files[0];if(!file||file.size>10*1024*1024){message.textContent='Please choose a file no larger than 10 MB.';return}message.textContent='Uploading…';try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});await request('/api/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:form.title.value,description:form.description.value,fileName:file.name,mediaType:file.type,content})});form.reset();message.textContent='Memory published.';load()}catch(err){message.textContent=err.message}};
document.querySelector('#refresh').onclick=load;load();
